def expand_people(base, R):
    people = deepcopy(base)
    def refs(*ids):
        result = []
        for i in ids:
            result.append(R(i, QUOTES.get(i), SOURCE_BOOKS.get(i)))
            result.extend(R(i, quote, SOURCE_BOOKS.get(i)) for quote in EXTRA_QUOTES.get(i, []))
        return result
    def t(text, *ids):
        return {'text': text, 'refs': refs(*ids)}
    def m(when, title, text, *ids):
        return {'when': when, 'title': title, 'text': text, 'refs': refs(*ids)}
    def rel(pid, label, *ids):
        return {'personId': pid, 'label': label, 'refs': refs(*ids)}
    def p(pid, name, courtesy, faction, role, lead, period, aliases, tags, paragraphs, milestones, relations, reading, note=None):
        people.append(dict(id=pid,name=name,courtesy=courtesy,faction=faction,role=role,lead=lead,period=period,aliases=aliases,tags=tags,paragraphs=paragraphs,milestones=milestones,relations=relations,reading=reading,note=note,eventIds=[]))
    def scope(text, *ids):
        return {'title':'本书材料范围','text':text,'refs':refs(*ids)}

    p('zhang-jiao','张角','本书未详','汉末','黄巾起事的组织者','宗教传播转为各地起兵，进入汉末战争的开端。','活动见于汉末、184年起事',['張角'],['黄巾','太平道'],[
        t('张角没有独立列传，他的行动主要在孙坚、张鲁等人的传记中出现。孙坚传记中平元年黄巾起事，称张角起于魏郡，以神灵为号召，派八名使者向各地传播，暗中联结响应者，并宣称“黄天泰平”。这段材料交代的是组织起事的方法，而没有完整记述他的家世、求学或早年经历。','v046-b0004'),
        t('裴注所引《典略》将张角的教法称为太平道，记师者持九节杖、用符祝与符水，并让病人叩头思过。书中把病愈与否解释为信道与否，这是当时传播教法的叙述，不能当作疾病治疗的可靠证据。《典略》又把太平道与汉中张脩的五斗米道并列，比较二者的组织与仪式。','v008-b0047-n01'),
        t('起兵后，各地焚烧郡县、攻击长吏，汉廷派皇甫嵩、朱儁统军镇压；孙坚募兵加入朱儁部，参与攻取宛城等战斗。因此张角与孙坚在本书中的联系，是起事一方与奉命讨伐一方的战争关系。《典略》简略说张角后来被诛，却没有在这里提供可重建完整终局的经过，本卡据此保留材料边界。','v046-b0004','v008-b0047-n01')],[m('起事之前','传播太平道','派使者传播教法，暗中连结各地。','v046-b0004'),m('184年','黄巾起兵','中平元年各地响应，汉廷派军讨伐。','v046-b0004'),m('起事之后','镇压与终局记载','孙坚随朱儁作战；《典略》仅简记角被诛。','v046-b0004','v008-b0047-n01')],[rel('sun-jian','孙坚参与汉廷讨伐黄巾','v046-b0004')],['046','008'],scope('本卡以孙坚传正文及张鲁传裴注的散见记载说明张角的组织和战争角色；字号、生卒与完整起事过程本书此处未详。','v046-b0004','v008-b0047-n01'))

    p('dong-zhuo','董卓','仲颖','汉末','以军队控制汉廷的权臣','从边地领兵进入京师，废立皇帝并引发讨董战争。','汉末—192年',['董仲颖','董仲穎','董卓'],['讨董','迁都','汉廷'],[
        t('董卓字仲颖，陇西临洮人。年轻时游历羌中，与豪帅结交，后来入羽林、从军立功。他曾把赏赐分给吏士，也在凉州战争中用决堰阻断追兵，保存所部。这些经历说明他进入京师以前已有军队与边地关系，并非仅凭朝廷官位获得力量；但讨黄巾时，他也有兵败抵罪的记录。','v006-b0002'),
        t('何进召董卓领兵入京，何进却先被杀。董卓迎回被宦官劫走的皇帝，又接收何氏部曲，使吕布杀丁原并合其众，取得京师兵权。他废少帝、立献帝，进为相国，用严刑与暴力威胁朝臣和百姓。原先经他任用的州郡长官联合讨伐，也使军事控制与地方反抗同时加剧。','v006-b0003','v006-b0005','v006-b0006'),
        t('关东兵起后，董卓迁天子至长安，焚烧洛阳、发掘陵墓，又在郿筑坞储粮。正文同时记滥刑、财物掠夺及钱币改制带来的困苦。初平三年，王允、士孙瑞与吕布合谋，董卓入宫时被杀。他的死亡没有立即恢复秩序，原部将李傕、郭汜随后攻陷长安，显示个人被除与军队网络瓦解是两件不同的事。','v006-b0007','v006-b0008','v006-b0011')],[m('入京之前','边地军功','从军并经营羌中关系。','v006-b0002'),m('189年','控制京师与废立','并合兵众，废少帝、立献帝。','v006-b0003','v006-b0005'),m('190年','迁都长安','关东起兵后迁帝并焚烧洛阳。','v006-b0007'),m('192年','遇刺身亡','王允等联络吕布，在宫门诛杀董卓。','v006-b0008')],[rel('sun-jian','孙坚在讨董战争中击破其军','v046-b0007'),rel('yuanshao','袁绍参与招卓入京，后与其决裂','v006-b0003','v006-b0020'),rel('zhang-liao','张辽曾率兵隶属董卓','v017-b0002')],['006','046'])

    p('sun-jian','孙坚','文台','孙吴','早期孙氏的领兵者','从郡县军务到讨董前线，为孙氏军队留下基础。','汉末—初平三年（正文纪年）',['孙文台','孫堅','武烈皇帝'],['黄巾','讨董','孙氏'],[
        t('孙坚字文台，吴郡富春人，早年做县吏。他十七岁遇海盗，以指挥包围的姿态使对方逃散，随后得到官府任用；又募兵参与讨伐许昌起事。黄巾战争时，朱儁请他为佐军司马，他集合乡里少年、商旅与淮泗精兵，攻宛先登立功。这支军队的形成，依靠的是地方招募和实际作战。','v046-b0002','v046-b0003','v046-b0004'),
        t('孙坚参加凉州军务，曾向张温列举董卓不服军令的罪状，主张处置董卓而未获采纳。任长沙太守后，他镇压区星等势力。董卓控制汉廷，各地举兵，孙坚北上与袁术合作，虽在梁东受挫，仍收合散兵，在阳人击破董卓军，迫使袁术恢复军粮供应，也拒绝董卓提出的和亲条件。','v046-b0005','v046-b0006','v046-b0007'),
        t('董卓西迁后，孙坚进入洛阳，修复被掘的陵墓，再退住鲁阳。后来袁术命他进攻刘表，孙坚击退黄祖、围襄阳，却在岘山行动时被黄祖军士射杀，部众由孙贲带回袁术处。他活着时属于汉末领兵者，本卡归入孙吴是便于索引孙氏事业；孙权称帝后才追谥他为武烈皇帝，不能把追尊当作在世称帝。','v046-b0008','v046-b0009','v046-b0010')],[m('184年','参与黄巾战争','随朱儁攻战，攻宛先登。','v046-b0004'),m('讨董期间','阳人获胜','受挫后重整部众，击破董卓军。','v046-b0007'),m('董卓西迁后','修复洛阳陵墓','进洛阳修陵，随后退住鲁阳。','v046-b0008'),m('初平三年（正文）','襄阳战死','奉袁术命攻刘表，被黄祖军士射杀。','v046-b0009')],[rel('dong-zhuo','讨董前线的敌手','v046-b0007'),rel('sun-ce','孙策承接其部曲','v046-b0013'),rel('sunquan','孙权之父，死后受其追尊','v046-b0010')],['046'])

    p('sun-ce','孙策','伯符','孙吴','江东根据地的开拓者','从袁术部下独立发展，把短暂征服转成孙氏根据地。','汉末—200年',['孙伯符','孫策','长沙桓王'],['江东','孙氏','继承'],[
        t('孙策字伯符，孙坚之子。父亲起兵时，他带母亲迁到舒，与周瑜交友，聚集士人；父死后，又在江都、曲阿等处辗转。投奔袁术后，袁术交还孙坚旧部，却屡次把许诺给孙策的郡守职位授给他人。孙策因此失望，转而请求帮助吴景等人平定江东，以少量初始兵众渡江扩大势力。','v046-b0012','v046-b0013','v046-b0014'),
        t('孙策击退刘繇，进取会稽，再破严白虎等地方势力，任命郡县长官，以张昭、张纮等为谋主。传记既记他作战猛锐，也记军令整肃和善于听取意见，解释士民为何愿意追随。袁术称帝时，孙策以书信责备并断绝关系，后来又乘刘勋外出，袭取庐江，进一步扩展江东的军队与地盘。','v046-b0015','v046-b0016','v046-b0018'),
        t('建安五年，曹操、袁绍在官渡相持，孙策准备袭许迎汉帝，尚未发动却被许贡门客袭伤。他在病重时召张昭等托付孙权，把印绶交给弟弟，并比较两人在阵战和举贤任能方面的长处，随后去世。江东事业由孙权承接，因此孙策的征服与继承安排应一起读；本卡孙吴标签指早期孙氏，长沙桓王也是后来的追谥。','v046-b0019','v046-b0020','v046-b0021')],[m('兴平元年','接收父亲旧部','从袁术，取得孙坚部曲。','v046-b0013'),m('渡江以后','建立江东根据地','破刘繇等，任命郡县长官。','v046-b0014','v046-b0015'),m('袁术称帝时','与袁术决裂','以书责袁术而绝交。','v046-b0016'),m('200年','受伤与托付孙权','袭许计划未发，受伤后移交印绶。','v046-b0019','v046-b0020')],[rel('sun-jian','继承其部曲与孙氏事业','v046-b0013'),rel('sunquan','临终把印绶及江东事业托付弟弟','v046-b0020'),rel('zhouyu','早年相友并聚集士人','v046-b0012')],['046'])

    p('cao-pi','曹丕','子桓','曹魏','曹魏的首位皇帝','继魏王位而代汉，仍面对江南未定与制度建设。','187—226年（正文）',['曹子桓','魏文帝','曹丕'],['代汉','吴王','继承'],[
        t('曹丕字子桓，是曹操的太子。正文记他生于中平四年，建安十六年任五官中郎将、副丞相，二十二年立为魏太子。曹操去世后，他先继丞相和魏王位，改年为延康，再经汉帝授玺绶、在繁阳设坛即位，改元黄初。要分清这两个阶段：承接曹操的魏王事业，与以皇帝名义建立曹魏，并不是同一时点。','v002-b0001','v002-b0013','v002-b0014'),
        t('即位后，曹丕奉汉帝为山阳公，调整朝廷官名和郡国制度。孙权遣使奉章，他派邢贞封孙权为吴王，加九锡；但吴蜀交战后的利益变化没有让魏吴关系稳定。黄初三年记孙权复叛，曹丕亲自南征，诸军并进而孙权临江拒守，说明封爵关系仍受实际军事实力与双方判断约束。','v002-b0015','v002-b0020','v002-b0028'),
        t('曹丕后来再组织舟师，至广陵临江观兵，却因严寒水道结冰而撤回。黄初七年病重，召曹真、陈群、曹休与司马懿受遗诏辅佐继承人，随后在洛阳去世。他喜好文学，并组织编纂《皇览》；帝纪同时写政治、军务与著述，使他不能只作为代汉仪式中的名字，也要放在未完成南方统一的处境中理解。','v002-b0036','v002-b0037','v002-b0038')],[m('217年','立为魏太子','在曹操晚年确定继承地位。','v002-b0001'),m('220年','由魏王到称帝','继魏王位，在繁阳即帝位。','v002-b0001','v002-b0014'),m('221年','封孙权吴王','使邢贞持节册封。','v002-b0020'),m('225年','广陵退军','因严寒冰封，舟师不能入江。','v002-b0036'),m('226年','托付后事','命曹真等四人辅嗣主后去世。','v002-b0037')],[rel('caocao','作为太子承接魏王位','v002-b0001'),rel('cao-rui','曹叡为其太子与继位者','v003-b0001'),rel('sunquan','曾封吴王，后再南征','v002-b0020','v002-b0028'),rel('sima-yi','命其受遗诏辅政','v002-b0037')],['002'])

    p('cao-rui','曹叡','元仲','曹魏','应对吴蜀战争的魏明帝','军事应变与宫室劳役并存，终年再托少主。','226—239年在位',['曹睿','曹元仲','魏明帝','曹叡'],['街亭','辽东','托孤'],[
        t('曹叡字元仲，曹丕之子，早年为曹操所爱。他历封武德侯、齐公、平原王，因为母亲被诛而迟未立为继承人，直到曹丕病重才立为皇太子，并在同日继皇帝位。即位之初，孙权攻江夏，他判断吴军难以久攻，魏方以增兵和山上举火应对，孙权退兵，呈现他面对边境战争的早期决策。','v003-b0001','v003-b0002'),
        t('诸葛亮首次北伐，天水、南安、安定响应，曹叡派曹真统军、张郃在街亭击败马谡，并亲到长安。以后诸葛亮再出，他又任司马懿抵御。辽东公孙渊与魏决裂，曹叡坚持派足兵力远征，也在雨水妨碍进攻时信任司马懿，不轻率召还；最终襄平被破，公孙渊首级送往京师。','v003-b0006','v003-b0013','v003-b0040'),
        t('帝纪之外的裴注还保存对他宫室营建的批评，董寻指出造像、土山等工程妨农劳民，曹叡虽然动怒却未追究其罪。景初三年病重，他召司马懿至卧内，把少子与后事交给司马懿和曹爽，随后去世。军事上的信任与继承时的共同辅政，并未保证下一代权力均衡，这成为曹芳朝冲突的起点。','v003-b0036-n03','v003-b0043')],[m('226年','继承帝位','曹丕病重立其为太子，随后即位。','v003-b0001'),m('228年','应对首次北伐','调曹真、张郃作战并到长安。','v003-b0006'),m('238年','平定辽东','支持司马懿远征公孙渊。','v003-b0037','v003-b0040'),m('239年','托孤与终年','托司马懿、曹爽辅佐少主。','v003-b0043')],[rel('cao-pi','承接父亲皇位','v003-b0001'),rel('zhuge-liang','其北伐的魏方应对者','v003-b0006'),rel('sima-yi','倚重其领兵并托付后事','v003-b0040','v003-b0043'),rel('cao-shuang','托付其与司马懿共同辅政','v003-b0043')],['003'])

    p('liu-shan','刘禅','公嗣','蜀汉','经历辅政与降魏的后主','继承蜀汉，在不同辅臣及战争条件下维持与失去政权。','223—263年在位；271年卒',['阿斗','刘公嗣','劉禪','后主','安乐公'],['继承','辅政','蜀亡'],[
        t('刘禅字公嗣，是刘备之子，父为汉中王时立为王太子，称帝后立为皇太子。刘备在永安去世，他十七岁在成都即位。初年南中存在反叛，朝廷派邓芝修复吴蜀关系，次年务农息民，诸葛亮随后南征平定四郡。因此他的继位处境不是安稳承接疆土，而是需要辅臣同时处理边地与外交。','v033-b0002','v033-b0003','v033-b0004','v033-b0005'),
        t('诸葛亮出屯汉中、多次北伐，刘禅在成都维持国家运转；孙权称帝时，双方约盟。诸葛亮去世后，蒋琬接掌政务，费祎随后承担主要军政，姜维又长期出兵。姜维传记黄皓等人在内弄权，并使刘禅搁置姜维对魏军准备的警告。读这一时期，应注意朝廷听取信息的渠道，及君主、辅臣、前线将领的关系变化。','v033-b0007','v033-b0009','v044-b0004','v044-b0014','v044-b0024'),
        t('景耀六年，魏军多路入蜀，邓艾击破绵竹后，刘禅采用谯周的建议请降，命守军放下兵器，官府财物不毁。邓艾受降以后，钟会之乱又使成都军民遭受掠夺。刘禅举家迁到洛阳，被封安乐县公，泰始七年去世。本书对他的评价强调任贤与受近臣影响的差别，不能只用一个宴乐故事替代这段国家经历。','v033-b0042','v033-b0043','v033-b0044','v033-b0045','v033-b0048','v033-b0049')],[m('223年','成都即位','刘备去世后袭位，时年十七。','v033-b0002'),m('223—225年','通吴与平南','派邓芝通好，诸葛亮平南中。','v033-b0003','v033-b0005'),m('234年以后','辅臣相继承担国事','诸葛亮后由蒋琬、费祎任主要军政。','v044-b0004','v044-b0014'),m('263年','向邓艾请降','绵竹失守后决定降魏。','v033-b0042','v033-b0044'),m('264—271年','迁洛阳与终年','受封安乐县公，后在洛阳去世。','v033-b0045','v033-b0048')],[rel('liubei','作为太子继承父亲皇位','v033-b0002'),rel('zhuge-liang','即位后倚重其主持军政','v035-b0008'),rel('jiang-wan','诸葛亮后任其接掌政务','v044-b0004'),rel('jiang-wei','搁置其警报，亡国后命其降魏','v044-b0024'),rel('deng-ai','向其军前降服','v033-b0044')],['033','044'])

    p('cao-shuang','曹爽','昭伯','曹魏','与司马懿共同受托的辅臣','辅政权力扩张，伐蜀失利，最终在高平陵变局中覆灭。','239—249年主要执政',['曹昭伯','曹爽'],['辅政','兴势','高平陵'],[
        t('曹爽字昭伯，曹真之子。年轻时以宗室谨重受到曹叡亲爱，逐步任城门校尉、武卫将军。曹叡病重时命他为大将军，与司马懿共同受遗诏辅佐曹芳。此后他听从丁谧建议，把司马懿转为太傅，名义上尊重，实际希望奏事先经自己，以控制事务轻重，共同辅政因此开始失去均衡。','v009-b0032','v009-b0034'),
        t('曹爽的弟弟分别掌禁军和近侍职务，何晏、邓飏、李胜等人成为其腹心。为建立威名，他不顾司马懿阻止，在正始五年大举伐蜀。军队从骆谷入山，关中及氐羌转输难以供应，牲畜死亡，民众困苦；蜀军据山阻挡，杨伟催他退军，他最终撤回。这场战争把朝廷的权力竞争转成了边地运输和军民的负担。','v009-b0035'),
        t('随后曹爽等人更加专政，司马懿称病避让。嘉平元年，曹芳出谒高平陵，曹爽兄弟随行，司马懿趁机控制洛阳并请求免其官。曹爽经过犹豫交出权力，后来朝廷以谋不轨论罪，曹爽与相关人员被夷三族。书中对他的失势既写长期权力布局，也写突发兵变中的决断，不能只把覆灭视作一次外出造成的偶然。','v009-b0036','v009-b0037','v009-b0038','v004-b0018')],[m('239年','共同受托辅政','与司马懿辅佐曹芳。','v009-b0034'),m('执政初期','控制奏事渠道','转司马懿为太傅，使奏事先由己。','v009-b0034'),m('244年','伐蜀退军','骆谷进军受阻，运输困难而撤回。','v009-b0035'),m('249年','失势与被诛','高平陵外出时免官，后被夷三族。','v004-b0018')],[rel('cao-rui','受其遗命辅佐少主','v009-b0034'),rel('sima-yi','共同辅政转为权力冲突','v009-b0034','v004-b0018'),rel('fei-yi','伐蜀时费祎领兵抵御','v044-b0015')],['009','004'])

    p('cao-mao','曹髦','彦士','曹魏','试图反抗司马氏的魏帝','有文学问难之才，皇权却受司马氏限制，最终死于冲突。','254—260年在位',['曹彦士','曹彥士','高贵乡公','高貴鄉公'],['皇权','司马氏','继承'],[
        t('曹髦字彦士，是曹丕之孙、东海定王曹霖之子。曹芳被废后，郭太后主张迎立曹髦，使他承接曹叡一系的皇位。帝纪记他入洛阳时以臣礼对待迎接者，随后即位。这次继承不是父死子继的平顺交接，而是在司马师主导废立之后，太后与权臣共同安排的人选进入皇帝位置。','v004-b0030','v004-b0027','v004-b0028'),
        t('曹髦即位后，司马师平定毌丘俭、文钦起兵，死于许昌，司马昭接掌大将军和辅政权。曹髦曾到太学，要求讲解《易》《尚书》《礼记》，追问各家解释的矛盾；也令群臣赋诗。材料呈现他的读书兴趣和判断欲望，但同时不断记司马昭获授军政权力与特殊礼遇，文学才能无法直接改变权力格局。','v004-b0032','v004-b0038','v004-b0039','v004-b0040','v004-b0047','v004-b0043'),
        t('甘露五年，曹髦率左右拔刃出宫，与司马昭一方发生武力冲突而死，年二十。正文主要保存太后令与司马昭奏言，裴注《汉晋春秋》则记他不愿坐受废辱，决意讨司马昭，必须辨明叙述立场。随后朝廷诛成济、安排王礼安葬，又由司马炎迎曹奂继位。帝纪所见的死亡与追责，是皇帝名位和权臣实权紧张关系的最终爆发。','v004-b0060','v004-b0060-n01','v004-b0061','v004-b0062','v004-b0064')],[m('254年','被迎立为帝','曹芳废后，在太后提议下入继。','v004-b0030','v004-b0027','v004-b0028'),m('255年','辅政者更替','司马师死，司马昭成为大将军。','v004-b0032'),m('256年','太学问难','与博士讨论经义及解释分歧。','v004-b0038','v004-b0039'),m('260年','出宫冲突身亡','率左右出宫，与前锋冲突被杀。','v004-b0060','v004-b0064')],[rel('sima-shi','其废曹芳后入继皇位','v004-b0027','v004-b0030'),rel('sima-zhao','在其辅政期间发动武力反抗','v004-b0060','v004-b0064'),rel('sima-yan','死后司马炎迎立曹奂','v004-b0062')],['004'],scope('曹髦死亡的正文保存太后令和司马昭奏言，不能把其中对“悖逆”的指控写成中立的事实结论；本卡据双方冲突、死亡及后续处置说明事件。','v004-b0060','v004-b0064'))

    p('sima-yi','司马懿','本书未详','曹魏','受托辅政并掌军的重臣','在西线、辽东和朝廷之间积累权力，最终除去曹爽。','魏文帝至曹芳时期；251年卒',['司馬懿','司马宣王','司馬宣王'],['辽东','北伐','高平陵'],[
        t('司马懿在本书常称司马宣王，没有独立的完整列传。曹丕临终时，他与曹真、陈群、曹休同受遗诏；曹叡朝又参与抵御吴军、讨孟达与对蜀作战。这些散见材料把他置于受托辅政和统军的交接处，应据具体官职与行动阅读，不能因为正文使用后来的尊号，就把他当时的身份写成晋朝皇帝。','v002-b0037','v003-b0003','v003-b0005','v003-b0013'),
        t('诸葛亮最后出兵时，司马懿与蜀军隔渭相持；此后曹叡派他率兵远征公孙渊。辽东雨水妨碍进攻，曹叡仍判断他能应变，最终司马懿攻破襄平，使公孙渊势力覆灭。景初三年，曹叡再召他入卧内，托付少主，命他与曹爽共同辅政。他由边境统将转入中央辅臣的变化，与皇位继承紧密相连。','v035-b0017','v003-b0040','v003-b0043'),
        t('曹爽逐步控制奏事渠道，司马懿则称病避让。嘉平元年曹芳谒高平陵，司马懿趁曹爽随行而发动行动，曹爽等免官后被夷三族。后来他又领兵处理王凌谋废帝、立曹彪的行动，王凌自杀、曹彪被赐死；同年司马懿去世。书中可见的是军事资历转成辅政权力的过程，早年生活与家族完整经历仍超出本卡材料范围。','v009-b0034','v009-b0036','v004-b0018','v004-b0021')],[m('226年','受曹丕遗诏','与曹真等辅佐曹叡。','v002-b0037'),m('234年','与诸葛亮相持','在渭南与蜀军长期相持。','v035-b0017'),m('238—239年','平辽东再受托','攻破襄平，又受曹叡托孤。','v003-b0040','v003-b0043'),m('249年','高平陵行动','奏免曹爽等并控制朝廷。','v004-b0018'),m('251年','王凌事件与终年','东征王凌后去世。','v004-b0021')],[rel('cao-pi','受其遗诏辅政','v002-b0037'),rel('cao-rui','为其领兵并再次受托','v003-b0040','v003-b0043'),rel('cao-shuang','从共辅少主到除去对方','v009-b0034','v004-b0018'),rel('sima-shi','其死后司马师接掌主要军政','v004-b0021')],['002','003','004','035'],scope('司马懿没有本书独立列传；本卡依据魏帝纪、曹爽传及诸葛亮传的散见材料。“宣王”为书中称谓，不表示他在所述年份已为晋帝；字号与完整早年本书此处未详。','v003-b0040','v004-b0021'))

    p('sima-shi','司马师','本书未详','曹魏','掌握废立权的大将军','承接辅政权力，调度吴蜀战争，并主导更换魏帝。','251—255年主要执政',['司馬師','司马景王','司馬景王'],['废立','东兴','淮南'],[
        t('司马师在本书多称司马景王，相关经历散见于曹芳、曹髦帝纪及诸将传。司马懿去世后，他由卫将军任抚军大将军、录尚书事，次年为大将军。邓艾提出边地与农业建议，司马师多有采用；这些记述显示他接掌的不只是某一支军队，而是兼及朝廷奏事、边地部署与国家资源的辅政权力。','v004-b0021','v004-b0022','v028-b0033','v028-b0034'),
        t('嘉平四年，魏军进攻吴国，在东关大败。裴注《汉晋春秋》记司马师承认自己未听建议，不把责任全部推给诸将。次年吴方诸葛恪围合肥新城、姜维在西线进兵，魏方以守城与调兵应对，最终两线缓解。面对同时发生的吴蜀压力，司马师的作用主要是调度和选择应对方向，不宜写成亲自赢得所有战斗。','v004-b0022','v004-b0022-n02','v004-b0023'),
        t('曹芳朝李丰、张缉等谋更换大臣，事情暴露后遭诛。随后司马师向太后提出废帝，曹芳被遣回齐国，曹髦被迎立，表明辅臣已经能左右皇位。正元二年毌丘俭、文钦在淮南起兵，司马师亲征，文钦败走吴国，毌丘俭被杀；司马师不久在许昌去世，司马昭继掌大将军和录尚书事，其权力延续又一次通过继承完成。','v004-b0027','v004-b0030','v004-b0032')],[m('251—252年','接掌军政','任抚军大将军、录尚书事，后为大将军。','v004-b0021','v004-b0022'),m('252年','东关失利','魏军攻吴败还；裴注记其承担决策责任。','v004-b0022','v004-b0022-n02'),m('254年','废曹芳立曹髦','向太后提出废帝并更换皇位人选。','v004-b0027','v004-b0030'),m('255年','平淮南后去世','出征毌丘俭、文钦，后卒于许昌。','v004-b0032')],[rel('sima-yi','其死后承接主要军政职权','v004-b0021'),rel('sima-zhao','死后司马昭接掌辅政','v004-b0032'),rel('cao-mao','废曹芳后迎立曹髦','v004-b0027','v004-b0030'),rel('deng-ai','采用其边地和农业建议','v028-b0033','v028-b0034')],['004','028'],scope('本卡从魏帝纪、邓艾传等散见材料说明其执政与战争角色，不补写本书未提供的完整早年。“景王”为书中称谓。','v004-b0021','v004-b0027'))

    p('sima-zhao','司马昭','本书未详','曹魏','曹魏末年的掌权者','接掌兄长的军政大权，平定淮南、组织灭蜀，为司马氏建晋铺路。','曹魏末年，255—265年执政',['司馬昭','司马文王','司馬文王','晋王'],['淮南','灭蜀','晋王'],[
        t('司马昭（211—265年）是司马懿的儿子、司马师的弟弟，也是司马炎的父亲。255年接掌辅政后，他实际掌握曹魏军政大权，皇帝的处境也越来越艰难。','v009-b0036-n02','v048-b0044-n01','v028-b0055','v004-b0085'),
        t('257—258年围攻寿春时，诸将急于破城，他却坚持围困，等待城中粮尽、生变。文钦被杀后，两个儿子逃来投降，他赦免二人，让他们绕城喊话：文钦的儿子尚且不杀，你们还怕什么？守军更加动摇，寿春最终被攻破。','v028-b0023','v028-b0024'),
        t('260年曹髦出兵时，已不愿再受他的控制。裴注记曹髦说“司马昭之心，路人所知也”，随后拔剑出宫，被贾充部下成济杀死。司马昭惊倒在地，叹道：“天下其谓我何！”弑君之变成为他一生无法绕开的污点。','v004-b0060-n01','v004-b0064'),
        t('263年组织灭蜀时，他重用钟会，也防着钟会。有人担心钟会带大军生变，他认为魏军将士思归，不会追随叛乱。264年钟会成都之乱果然被军士平定。蜀亡后，他与刘禅的问答，又留下了“此间乐，不思蜀”的故事。','v028-b0058','v028-b0067','v028-b0068','v033-b0048-n01'),
        t('264年进封晋王后，司马氏离皇位又近了一步。265年，司马昭去世，司马炎继承晋王之位，随后受禅建晋。司马昭没有亲自称帝，他留下的权力和地位，成了儿子开国的基础。','v004-b0077','v004-b0085','v004-b0086')],[
        m('255年','接掌辅政','司马师去世后，带军返回洛阳，接任大将军、录尚书事。','v028-b0055'),
        m('257—258年','围攻寿春','率军围困诸葛诞，赦免文鸯、文虎，最终攻破寿春。','v028-b0023','v028-b0024'),
        m('260年','曹髦出兵与被杀','曹髦率人出宫反抗，死于贾充部下成济之手。','v004-b0060-n01'),
        m('263年','组织灭蜀','部署钟会、邓艾等分道进兵，蜀汉灭亡。','v028-b0058'),
        m('264年','钟会之乱与晋王进封','钟会反叛被军士平定；同年司马昭由晋公进为晋王。','v028-b0068','v004-b0077'),
        m('265年','去世与晋国承继','去世后司马炎承袭晋王，同年受魏禅位建立西晋。','v004-b0085','v004-b0086')],[rel('sima-shi','哥哥去世后，由他接掌辅政','v028-b0055'),rel('sima-yan','儿子承袭晋王位，随后建立西晋','v004-b0085','v004-b0086'),rel('zhong-hui','重用其伐蜀，也提防其反叛','v028-b0058','v028-b0068'),rel('cao-mao','在其掌权时率人出宫反抗','v004-b0060-n01')],['004','028','033'],scope('《三国志》没有为司马昭单独立传，生平主要见于魏帝纪和钟会等人的传记；曹髦出宫、刘禅宴饮的细节见裴注《汉晋春秋》。“文王”是书中称谓，司马昭生前并未称帝。','v004-b0085','v004-b0086'))
    portrait = people[-1]
    portrait['relations'].insert(0, rel('sima-yi','父亲；其后兄弟二人先后掌握曹魏军政','v009-b0036-n02','v048-b0044-n01'))
    next(person for person in people if person['id']=='sima-yi')['relations'].append(rel('sima-zhao','儿子；后来接掌辅政，进封晋王','v009-b0036-n02','v048-b0044-n01','v004-b0077'))
    portrait['lifespan'] = dict(text='211—265年',sourceTitle='《晋书·文帝纪》',sourceUrl='https://zh.wikisource.org/wiki/晉書/卷002#文帝',quote='秋八月辛卯，帝崩于露寢，時年五十五。',note='生年按咸熙二年（265）去世、享年五十五逆推；不是原书直接记载的出生日期。')
    for paragraph, links in zip(portrait['paragraphs'], [
        [('255年接掌辅政','sima-zhao-regency')],
        [('257—258年围攻寿春','shouchun-siege')],
        [('260年曹髦出兵','cao-mao-death')],
        [('263年组织灭蜀','fall-shu'),('264年钟会成都之乱','zhong-hui-rebellion')],
        [('264年进封晋王','jin-founding'),('受禅建晋','jin-founding')],
    ]):
        paragraph['eventLinks'] = [dict(label=label,eventId=eid) for label,eid in links]
    for milestone, event_ids in zip(portrait['milestones'], [['sima-zhao-regency'],['shouchun-siege'],['cao-mao-death'],['fall-shu'],['zhong-hui-rebellion'],['jin-founding']]):
        milestone['eventIds'] = event_ids

    p('sima-yan','司马炎','本书未详','西晋','承袭晋王并接受魏禅位者','从辅政继承者到晋朝皇帝，最后完成对吴战争。','260—280年本卡主要材料',['司馬炎','晋武帝','晉武帝'],['代魏','继承','灭吴'],[
        t('司马炎在本书没有独立本纪，早期明确行动见于曹髦死后的皇位安排：他持节北迎常道乡公曹奂，使其入继曹叡一系。后来任中抚军，副相国事务，再进为抚军大将军，成为晋世子。这些官职和称号表明他先在魏朝与晋国之间取得继承地位，不能把迎立魏帝时的他提前写成西晋皇帝。','v004-b0062','v004-b0078','v004-b0080','v004-b0083'),
        t('司马昭获得进一步礼遇时，晋世子被改称太子。咸熙二年司马昭去世，司马炎承袭晋王位，统摄政务，仪仗典册沿用原安排。年底魏帝命群臣设坛南郊，遣使奉玺绶册书禅位于晋嗣王，魏帝随后迁往金墉城。本书以魏朝末年的笔法记这一交接，呈现父亲权力基础怎样转成新朝皇位。','v004-b0085','v004-b0086'),
        t('孙皓传继续记录晋方对吴的行动。天纪三年冬，晋军分路进攻，杜预向江陵，王濬、唐彬沿江东下，其他诸军各有方向。翌年吴军各处败退，王濬先至受孙皓降，晋廷封孙皓为归命侯。由此可见受禅与统一之间相隔的政治、军事过程；本卡只连接本书所见交接与战争，不用外书补出司马炎完整一生。','v048-b0042','v048-b0044','v048-b0047')],[m('260年','迎立曹奂','持节北迎常道乡公。','v004-b0062'),m('264年','成为晋世子','先副相国事务，再确定继承地位。','v004-b0078','v004-b0083'),m('265年','承袭与受禅','司马昭死后袭晋王位，年底魏禅晋。','v004-b0085','v004-b0086'),m('279—280年','晋灭吴','晋军分路征吴，孙皓最终降服。','v048-b0042','v048-b0047')],[rel('sima-zhao','承袭其晋王位与军政基础','v004-b0085'),rel('wang-jun','晋方征吴水军统将','v048-b0042'),rel('du-yu','晋方征吴江陵方向统将','v048-b0042'),rel('sun-hao','晋廷接受归降并授归命侯','v048-b0047')],['004','048'],scope('本书只散见司马炎在魏末、晋初的行动，缺其独立本纪；本卡不补写字号、生卒或完整施政，只依据魏末帝纪和孙皓传串联晋国继承、受禅与灭吴。','v004-b0085','v004-b0086','v048-b0042'))

    p('jiang-wan','蒋琬','公琰','蜀汉','诸葛亮之后的主要辅臣','以供应和持重稳定蜀汉，再调整对魏用兵方向。','刘备入蜀时期—246年',['蒋公琰','蔣琬'],['继承','治理','汉中'],[
        t('蒋琬字公琰，零陵湘乡人，随刘备入蜀，任广都长。刘备见他事务不理又饮酒，欲加重罪，诸葛亮认为他是国家可用之才，劝重新观察，蒋琬才免死而被免官。后来他进入丞相府，诸葛亮出兵时与张裔管理留府事务，持续供应兵员粮食。由县令争议到后方组织者，是其被识拔与实际能力发挥的过程。','v044-b0002','v044-b0003'),
        t('诸葛亮密告刘禅，自己若不幸，后事宜付蒋琬。诸葛亮去世后，蒋琬任尚书令、大将军、录尚书事等职。面对新丧统帅的危惧，他的举止平静，使群臣逐渐信服；对杨戏沉默与杨敏批评也不急于报复，强调不能按个人好恶用刑。传记把权力交接与日常待人连写，显示稳定国事也来自处理分歧的方式。','v044-b0003','v044-b0004','v044-b0005'),
        t('蒋琬驻汉中后，认为诸葛亮经秦川的进军道路艰险、运输困难，想造船由汉沔进击魏兴、上庸。但疾病阻碍出发，群议又担忧失利后难以退还，费祎、姜维来传达朝廷意见。蒋琬遂调整方案，支持姜维向凉州发展，自己在涪作为后继，最终因病去世。这说明承接诸葛亮事业并非重复同一条进军路线。','v044-b0006','v044-b0007','v044-b0008')],[m('刘备入蜀以后','诸葛亮识拔','广都任职受责时获诸葛亮救护。','v044-b0002'),m('227年以后','负责留府供应','诸葛亮出兵时供应兵粮。','v044-b0003'),m('234年','接掌主要军政','诸葛亮死后任尚书令、大将军等。','v044-b0004'),m('驻汉中后','调整进军方案','水路进攻受议，转为支持凉州方向。','v044-b0006','v044-b0007'),m('246年','病逝','还住涪，延熙九年卒。','v044-b0008')],[rel('zhuge-liang','受识拔并被推荐继承后事','v044-b0002','v044-b0003'),rel('fei-yi','其接替尚书令并商议军事调整','v044-b0014','v044-b0006'),rel('jiang-wei','支持其向凉州进兵','v044-b0007'),rel('liu-shan','诸葛亮向刘禅推荐其接掌后事','v044-b0003','v044-b0004')],['044'])

    p('fei-yi','费祎','文伟','蜀汉','调和军政与外交的辅臣','反复使吴、协调将领，接掌国事并限制大规模用兵。','刘备定蜀时期—253年',['费文伟','费禕','費禕','费祎'],['外交','兴势','继承'],[
        t('费祎字文伟，江夏鄳人，少年丧父，随族父入蜀游学，刘备定蜀后留在益州。他与董允齐名，遇到简陋车乘也能安然赴会。刘禅即位后，他任黄门侍郎，诸葛亮南征归来特别与他同车，随后派他出使孙吴。面对孙权及吴方士人的问难，他据理回答，获孙权称许，多次承担两国之间的联络。','v044-b0012','v044-b0013'),
        t('诸葛亮北伐时，费祎任参军、中护军与司马。魏延、杨仪争执激烈，甚至拔刀相向，他常入座劝解，使两人仍能在诸葛亮生前发挥作用。诸葛亮死后，费祎任后军师，再代蒋琬为尚书令，后来为大将军、录尚书事。延熙七年魏军进至兴势，他率兵赴援，敌军退走；传记强调其临急不乱与调和事务的能力。','v044-b0014','v044-b0015'),
        t('费祎主持国事时，虽驻在外，奖惩仍要先征求他的判断。姜维想大举向西方进攻，他常加以节制，给兵不超过万人；因此他的接掌也影响蜀汉资源如何用于战争。延熙十六年岁首宴会上，费祎饮醉，被魏降人郭循刺杀。此后姜维能率数万人出兵，前后相读可见辅臣死亡与军事政策变化的联系。','v044-b0015','v044-b0016','v044-b0019','v044-b0020')],[m('诸葛亮南征以后','多次出使孙吴','负责问难应答与两国往来。','v044-b0013'),m('北伐时期','调和魏延杨仪','劝解将领矛盾以维持共事。','v044-b0014'),m('蒋琬之后','接掌军政','代为尚书令，后任大将军。','v044-b0014'),m('244年','赴兴势御魏','率兵增援，魏军退走。','v044-b0015'),m('253年','宴会遇刺','岁首饮宴，被郭循杀害。','v044-b0016')],[rel('zhuge-liang','受其信任承担外交与军事协调','v044-b0013','v044-b0014'),rel('jiang-wan','继其尚书令与主要军政职务','v044-b0014'),rel('jiang-wei','限制其大举出兵的规模','v044-b0019'),rel('cao-shuang','兴势之役抵御其伐蜀','v044-b0015','v009-b0035')],['044'])

    p('jiang-wei','姜维','伯约','蜀汉','蜀汉后期的主要统将','在西方反复争取战果，最终守剑阁并卷入钟会之乱。','228年入蜀—264年',['姜伯约','姜維'],['北伐','段谷','蜀亡'],[
        t('姜维字伯约，天水冀人，早年为魏方郡吏。诸葛亮首次北伐时，天水太守怀疑随行者而弃他们入城，姜维回冀也被拒，遂投诸葛亮，随退军入蜀并与母亲失散。诸葛亮称赞他忠勤、精密、知兵，准备培养其军务能力。姜维入蜀并非一个简单的主动改换阵营故事，而与地方官的猜忌和城门关闭相连。','v044-b0018'),
        t('诸葛亮死后，姜维逐步任镇西大将军、卫将军，与费祎共录尚书事。他熟悉西方风俗，想联络羌胡取得陇西，但费祎限制兵力。费祎死后，他扩大出兵，在洮西大破王经，围狄道却被陈泰解围；次年因胡济失约，段谷之战遭邓艾重创，军民怨责，姜维请求自贬。战果与资源消耗同时构成后期北伐的面貌。','v044-b0019','v044-b0020','v044-b0021'),
        t('姜维后来调整汉中守法，却在侯和败后留住沓中，又因黄皓等人的排挤不返成都。他对钟会备战的警告被搁置，魏军入蜀后遂退守剑阁，使钟会不能攻克。邓艾绕道抵成都，刘禅命姜维投降。钟会厚待他，又谋借蜀兵反叛；魏军士卒发动，姜维与钟会同被杀。亡国、降军与兵变，是其最后连续而不同的处境。','v044-b0023','v044-b0024','v044-b0025')],[m('228年','投诸葛亮入蜀','天水、冀城拒纳后随蜀军撤回。','v044-b0018'),m('253—255年','扩大西线用兵','费祎死后增兵，洮西获胜却未取狄道。','v044-b0020'),m('256年','段谷失利','胡济未会师，败于邓艾并自请贬职。','v044-b0021'),m('263年','守剑阁后奉命降魏','拒钟会，却因成都受降而停止抵抗。','v044-b0024'),m('264年','死于钟会之乱','钟会欲授其蜀兵，兵变中同死。','v044-b0025')],[rel('zhuge-liang','入蜀后受到军务培养','v044-b0018'),rel('fei-yi','同录尚书事，却受其用兵限制','v044-b0019'),rel('deng-ai','段谷、侯和与蜀亡时期的对手','v044-b0021','v044-b0024'),rel('zhong-hui','剑阁对敌，受降后又被卷入其反叛','v044-b0024','v044-b0025')],['044'])

    p('deng-ai','邓艾','士载','曹魏','从屯田议策到灭蜀的统将','以地理与运输筹划战争，绕道取蜀后又遭逮捕和杀害。','魏前中期—264年',['邓士载','鄧艾'],['屯田','段谷','灭蜀'],[
        t('邓艾字士载，义阳棘阳人，早年随母亲迁到汝南，以典农部民身份生活，后任典农属吏。他常观察山川地形，思考军营部署，受到司马懿赏识而入朝；勘察陈项至寿春一带后，提出修渠、积粮与军屯建议。传记把其军事能力放在农政、水利和运输的实际问题上，说明战场判断也来自平日对地形与资源的考察。','v028-b0028','v028-b0029'),
        t('邓艾在西线与郭淮抵御姜维，判断蜀军可能回袭，连夜抢占洮城而免于失守。他参加淮南战争后，又救狄道围困，预测姜维仍会来攻，提前布置，随后在段谷击败姜维，升镇西将军、都督陇右。此后仍在长城和侯和等处与姜维交战，其胜利依赖连续的情势判断，不只是后来穿行阴平的一次冒险。','v028-b0030','v028-b0035','v028-b0037','v028-b0038'),
        t('景元四年灭蜀，邓艾先牵制姜维，再从阴平穿无人险道，经江由至绵竹，击败诸葛瞻，接受刘禅降服。他约束士卒、任命降臣，却与司马昭在自行处置权限上发生分歧，钟会等又告其悖逆，遂被槛车征还。钟会死后旧部迎回邓艾，卫瓘派田续追杀，邓艾与子邓忠俱死；平蜀大功与战后失势在本书中紧接出现。','v028-b0038','v028-b0039','v028-b0040','v028-b0043','v028-b0044')],[m('入朝前后','勘察与屯田建议','考察地形，提出运输及屯田方案。','v028-b0028','v028-b0029'),m('256年','段谷击败姜维','预判出兵，争险后大破蜀军。','v028-b0037'),m('263年','阴平进军灭蜀','绕行险道，破绵竹并受刘禅降。','v028-b0039','v028-b0040'),m('263—264年','被收与遭杀','遭告发后被囚，旧部迎回又被杀。','v028-b0043','v028-b0044')],[rel('sima-yi','得到其赏识而入朝','v028-b0028'),rel('jiang-wei','长期在西线交战','v028-b0030','v028-b0037'),rel('liu-shan','进成都接受其降服','v028-b0040'),rel('zhong-hui','同伐蜀，后遭其告发','v028-b0043','v028-b0063')],['028'])

    p('zhong-hui','钟会','士季','曹魏','伐蜀统帅与失败的叛乱者','筹谋和军权使其得势，灭蜀之后却无法掌握将士。','魏前中期—264年',['钟士季','鍾會','钟会'],['淮南','灭蜀','兵变'],[
        t('钟会字士季，颍川长社人，是钟繇的小儿子，少年以聪敏闻名，长大后博学，精于名理与各种技艺。他先任秘书郎、中书侍郎，随司马师征毌丘俭时掌机密。司马师死后，钟会与傅嘏筹划，使司马昭带军返回洛阳继掌辅政，因此他早期的升迁已同司马氏权力交接连在一起。','v028-b0053','v028-b0054','v028-b0055'),
        t('诸葛诞起兵时，钟会随司马昭至寿春，借全氏家族的矛盾伪作书信，使吴援将领以为家属将被诛而出降。寿春破后，他得到更深信任，也参与朝廷事务。司马昭欲大举伐蜀，钟会赞成并共同研究地形，后领十余万军入汉中，破阳安关，却在剑阁遭姜维拒守；蜀亡的直接突破则由邓艾绕道完成。','v028-b0057','v028-b0058','v028-b0060'),
        t('刘禅降后，钟会接收姜维等军队，任用蜀地官员，受拜司徒。他告发邓艾专擅，把其军队一并掌握，随后谋反，打算以姜维率蜀兵为前驱，自己进关中。因担心司马昭前来，他加速行动，囚禁军官、替换将领，却未能控制士卒与被囚者的联系。军队发动攻城，钟会与姜维被杀，其成功谋略与叛乱失败形成鲜明的前后结果。','v028-b0062','v028-b0063','v028-b0064')],[m('255年','参与司马昭继掌辅政','与傅嘏谋使司马昭回洛阳。','v028-b0055'),m('257—258年','寿春筹谋','伪作全氏书信促吴援出降。','v028-b0057'),m('263年','率军入蜀','破关后受阻剑阁，后接受姜维等降。','v028-b0058','v028-b0060'),m('263—264年','告发邓艾并掌军','264年初邓艾被收后独掌大军。','v028-b0063','v004-b0077'),m('264年','反叛兵败','囚军官而军士发动，兵变中死亡。','v028-b0063','v028-b0064')],[rel('sima-zhao','受信任筹划并统军伐蜀','v028-b0058'),rel('deng-ai','共同伐蜀，后构陷其专擅','v028-b0063'),rel('jiang-wei','由剑阁对手到叛乱合作者','v028-b0060','v028-b0063'),rel('du-yu','杜预以长史在其军中','v044-b0025')],['028'])

    p('sun-hao','孙皓','元宗','孙吴','孙吴的末代皇帝','在继承危机中被迎立，苛政与战败最终使吴国降晋。','264—280年在位；284年卒',['孙彭祖','孙皓宗','孫皓','归命侯'],['继承','苛政','吴亡'],[
        t('孙皓字元宗，又名彭祖、字皓宗，是孙权之孙、孙和之子。孙休去世时，蜀已亡，交趾反叛，吴国希望有成年君主应对危局；万彧称赞其才识好学，濮阳兴、张布遂劝太后迎立。孙皓即位后却骄暴多忌，兴、布后悔而遭诛。把立嗣时的期待与即位后的行为并读，能看见继承人选择和实际执政之间的落差。','v048-b0024','v048-b0025'),
        t('孙皓迁都武昌，后又回建业，杀害孙休皇后及子嗣，宫室工程和处罚持续增加。陆凯曾提醒晋已兼有巴蜀，不应轻率求战，孙皓却仍怀窥取北方之意；陆抗死后，边防又失重臣。正文记宴会时强迫群臣醉酒，再由专人报告过失加罪，后宫滥杀和繁重工程导致上下离心，这些制度性恐惧削弱了臣下尽力的意愿。','v048-b0026','v048-b0027','v048-b0035','v048-b0043'),
        t('天纪三年冬，晋军分路进攻，杜预向江陵、王濬沿江东下，各地吴军败退。孙皓曾寄望陶濬新集水军，却在出发前遭部众逃散，只得分遣使者向晋将奉书请降。王濬先到受降，孙皓举家西迁，在洛阳受封归命侯，太康五年去世。这一结局同时来自长期内部离心与多路军事压力，不能只用末代君主的个人恶名解释全部战争。','v048-b0042','v048-b0044','v048-b0046','v048-b0047')],[m('264年','被迎立为帝','危局中因成年与才识评价入继。','v048-b0024'),m('264—265年','清除拥立者与旧皇室','诛兴布，逼杀景后等。','v048-b0025','v048-b0026'),m('279年','晋军分道征吴','各军向江陵、武昌与江下游进兵。','v048-b0042'),m('280年','向晋请降','新集水军逃散，向各路晋将求降。','v048-b0046','v048-b0047'),m('284年','洛阳终年','太康五年死于洛阳。','v048-b0047')],[rel('sunquan','孙权之孙，继承孙氏吴国','v048-b0024'),rel('sima-yan','降晋后由晋廷授归命侯','v048-b0047'),rel('wang-jun','由其最先接受降服','v048-b0047'),rel('du-yu','其攻江陵使吴防线失守','v048-b0042','v048-b0044')],['048'])

    p('wang-jun','王濬','本书未详','西晋','沿江征吴的水军统将','蜀地造船、顺流进军，最先至吴都接受孙皓降服。','晋初至280年相关行动',['王浚','王濬'],['造船','灭吴','受降'],[
        t('王濬没有本书独立列传，他在孙皓传中作为晋方征吴将领出现。裴注所引干宝《晋纪》记他在蜀治船，吴彦取顺江漂下的木片给孙皓看，判断晋将进攻，建议增建平守兵，孙皓未从。这段材料说明上游造船已经留下可被下游察觉的迹象，但没有提供可补成完整船队规模或造船技术史的细节。','v048-b0047-n02'),
        t('天纪三年冬，晋发动分路征吴，王濬以龙骧将军身份与广武将军唐彬浮江东下。其他晋军分别攻江陵、武昌、夏口和下游要地，太尉贾充为大都督。翌年正文记王濬、唐彬所至吴方瓦解，无力有效抵御。把各路部署并列起来，可见王濬的顺流进军属于整体攻势的一环，不能抹去其他方向的作战作用。','v048-b0042','v048-b0044'),
        t('孙皓原想以陶濬新集水军阻挡蜀船，却在出发前夜遇到士卒逃散；王濬将至，司马伷、王浑也逼近，孙皓分别向诸将请降。王濬最先抵达，解开孙皓束缚、焚棺并接见，完成军事受降；孙皓的封爵与迁洛阳则由晋廷处置。这些具体动作构成他的本书角色，本卡不据外部传记补写字号、出生、后续官场争议和终年。','v048-b0046','v048-b0047')],[m('征吴之前','蜀地治船','《晋纪》记造船木片引起吴彦警告。','v048-b0047-n02'),m('279年冬','沿江东下','与唐彬率水军参加多路攻势。','v048-b0042'),m('280年春','吴军瓦解','正文记两军所至少有有效抵御。','v048-b0044'),m('280年','最先受降','先抵吴都，解孙皓缚并焚棺。','v048-b0047')],[rel('sun-hao','最先到达并接受其降服','v048-b0047'),rel('du-yu','分担灭吴的水军与江陵方向','v048-b0042'),rel('sima-yan','晋方征吴部署中的水军统将','v048-b0042')],['048'],scope('本卡仅依据孙皓传及裴注《晋纪》的造船、进军和受降记载；没有王濬独立传记，字号、生卒及后续经历本书此处未详。兼容别写“王浚”。','v048-b0042','v048-b0047','v048-b0047-n02'))

    p('du-yu','杜预','本书未详','西晋','由灭蜀军幕到江陵统将','散见于钟会军中与晋灭吴部署，连接两次战争的角色。','263—280年本书相关行动',['杜預','杜预'],['灭蜀','江陵','灭吴'],[
        t('杜预没有本书独立列传，在姜维传中明确以钟会长史身份出现。蜀亡后，钟会厚待姜维，出行同车、入座同席，并向杜预称赞姜维的才识，把他与中原名士比较。这里能确定的是杜预在钟会军幕的位置和见闻，不能由一句对话推断他支持钟会随后反叛，更不能补写本书没有展开的完整仕途。','v044-b0025'),
        t('邓艾被收、钟会兵变之后，卫瓘派田续追杀邓艾。裴注所引《汉晋春秋》记杜预批评卫瓘借怨报复而不能正当约束部下，认为高位名士应承担更严的责任，卫瓘闻言前来谢过。此段属于另一层史料，呈现杜预对战后处置的评价；它不能替代正文的杀艾记载，也不能据此断定所有人物的内心动机。','v028-b0044','v028-b0044-n01'),
        t('到孙皓传记晋征吴时，杜预已经以镇南将军身份向江陵进军，与王濬等沿江水军及其他方向部队分担攻势。天纪四年，正文记他斩江陵督伍延，与各路晋军战胜相连，孙皓随后请降。江陵的失守是吴国防线瓦解的一部分，本卡把这一结果与早年的军幕角色相接，只说明材料可见的变化，不扩写其经学著述、家世或终年。','v048-b0042','v048-b0044','v048-b0046')],[m('263年蜀亡后','钟会军中长史','钟会向其称许姜维。','v044-b0025'),m('264年相关裴注','评论杀艾处置','《汉晋春秋》记其批评卫瓘。','v028-b0044-n01'),m('279年冬','奉命向江陵','作为镇南将军参加分路征吴。','v048-b0042'),m('280年春','击破江陵防线','正文记斩江陵督伍延。','v048-b0044')],[rel('zhong-hui','在其军中任长史','v044-b0025'),rel('jiang-wei','听钟会比较其与中原名士','v044-b0025'),rel('wang-jun','灭吴时分别进江陵与沿江东下','v048-b0042'),rel('sun-hao','攻破江陵的晋方统将','v048-b0044')],['044','028','048'],scope('杜预材料散见于姜维传、邓艾传裴注和孙皓传；本卡不把它改写为完整晋书传记。字号、生卒、经学与其他施政在本卡证据范围内未详。','v044-b0025','v028-b0044-n01','v048-b0042'))

    p('zhang-liao','张辽','文远','曹魏','北方战场与合肥守备的将领','历经阵营变动，归曹后以突击和守城稳住东线。','汉末—222年',['张文远','張遼','刚侯'],['白狼山','合肥','东线'],[
        t('张辽字文远，雁门马邑人，先做郡吏，再为丁原募兵，后随所部归董卓、吕布。曹操破吕布时，他率军投降，逐步参与北方征战。围昌豨时粮尽将退，张辽观察对方射箭减少、反复注视，判断其犹豫，独自劝降；曹操虽肯定归附结果，也责其冒险。传记因此同时写临阵判断和行事尺度。','v017-b0002'),
        t('北征柳城时，张辽劝曹操交战，获授军旗，击破乌丸并斩蹋顿；以后又处理营中惊乱，攻取陈兰、梅成所据险山。曹操西征张鲁，留张辽、乐进、李典守合肥。孙权来攻，张辽按预定部署募八百敢战士先击，突至孙权麾下，再返回救出被围部众，使守军士气安定，吴军攻城不克后退走。','v017-b0002','v017-b0003','v017-b0004'),
        t('孙权撤军时，张辽继续追击，几乎擒获对手，获升征东将军。关羽围樊城，他奉召赴援但未到即已解围，这一点应与徐晃的实际救援分清。曹丕即位后多次礼遇他，患病时派医探望；后来仍随曹休临江征吴，参与击吕范，最终病逝江都。合肥名声之外，他的晚年仍包含调动、疾病与持续领军的压力。','v017-b0004','v017-b0005')],[m('曹操破吕布时','率众归曹','从吕布部将转入曹操军队。','v017-b0002'),m('207年','北征柳城','劝战并率突击，斩蹋顿。','v017-b0002'),m('215年','合肥守战','先击孙权军、救部众，再追击退军。','v017-b0004'),m('219年','奉召援樊','未抵达时徐晃已解曹仁之围。','v017-b0005'),m('222年','病中征吴与终年','随曹休临江击吴，后病逝江都。','v017-b0005')],[rel('caocao','归降后长期受命征战','v017-b0002','v017-b0004'),rel('sunquan','合肥攻守的主要对手','v017-b0004'),rel('cao-pi','受其礼遇，晚年仍领军征吴','v017-b0005'),rel('dong-zhuo','早年率所部隶属董卓','v017-b0002')],['017'])

    by_id = {person['id']: person for person in people}
    # Existing cards retain their core biographies; replace only the requested late arcs.
    by_id['sun-jian']['note'] = {'title':'孙坚终年的纪年差异','text':'正文写初平三年，裴注所引《英雄记》则记初平四年正月七日；同注还保存射杀、落石致死等差异。本卡按正文注明纪年，不把不同记载拼成无争议的单一经过。','refs':[R('v046-b0009','初平三年，術使堅征荊州，擊劉表。'),R('v046-b0009-n01','英雄記曰：「堅以初平四年正月七日死。」','《英雄记》')]}
    by_id['caocao']['relations'] += [rel('cao-pi','太子继承其魏王位','v002-b0001'),rel('zhang-liao','归降后受命征战与守合肥','v017-b0002','v017-b0004')]
    by_id['liubei']['paragraphs'][2] = t('章武元年，刘备在成都称帝，立刘禅为皇太子，建立蜀汉的帝号与继承安排。同年，他因孙权袭取关羽后方而亲率诸军东征，拒绝吴方求和；次年夷陵失败，蜀军损失严重，刘备退到永安。病重时，他召诸葛亮托付后事，让刘禅敬事丞相，随后去世。创业、称帝与最后一战连读，能看到重建队伍的能力，也能看到战略选择对已经建立的国家造成的代价。','v032-b0032','v032-b0033','v032-b0035','v032-b0036','v032-b0037','v035-b0007')
    by_id['liubei']['milestones'][-1] = m('221—223年','称帝、东征与托孤','221年称帝，东征败后托孤诸葛亮。','v032-b0032','v032-b0033','v032-b0035','v032-b0037')
    by_id['liubei']['relations'].append(rel('liu-shan','立为太子，临终安排其继位','v033-b0002','v032-b0037'))
    by_id['sunquan']['paragraphs'][2] = t('刘备东征时，孙权任陆逊统军，在夷陵获胜。魏方先封他吴王，后来魏吴交战，他于黄武元年改年，临江抵御曹丕，吴蜀也开始恢复联系。黄龙元年他正式称帝，将江东事业转为孙吴帝国；晚年太子之位经历更换，最终孙亮继位。神凤元年孙权去世。这条经历既包含对外战与和，也包含国家建立后的内部继承问题，不能在229年称帝处结束。','v058-b0009','v002-b0020','v047-b0025','v047-b0034','v047-b0064','v048-b0002','v048-b0003')
    by_id['sunquan']['milestones'] = by_id['sunquan']['milestones'][:3] + [m('221—229年','吴王、黄武与称帝','221年受魏封吴王；222年黄武改年拒魏，229年称帝。','v002-b0020','v047-b0025','v047-b0034'),m('252年','去世与继承','孙权去世，孙亮继位。','v047-b0064','v048-b0003')]
    by_id['sunquan']['relations'] += [rel('sun-ce','承接兄长印绶与江东事业','v046-b0020'),rel('cao-pi','先受封吴王，后临江抗其军','v002-b0020','v047-b0025')]
    by_id['zhuge-liang']['paragraphs'][2] = t('最后一次出兵，诸葛亮在五丈原与司马懿相持，以屯田准备长期驻军，随后病逝。对于后事，他此前已密表刘禅推荐蒋琬；对于年轻的姜维，则称许其忠勤与军事判断，准备进一步培养。这使他的生平还连接到后续辅政和北伐。陈寿肯定其治理与赏罚公正，也对连年出兵未成功提出疑问；生前安排与史家评语合读，更能理解其既组织国家、又未完成北定目标的处境。','v035-b0017','v044-b0003','v044-b0018','v035-b0045')
    by_id['zhuge-liang']['relations'] += [rel('jiang-wan','密表刘禅推荐其承担后事','v044-b0003'),rel('jiang-wei','称许其知兵并准备培养','v044-b0018'),rel('fei-yi','派其使吴并倚其协调将领','v044-b0013','v044-b0014'),rel('sima-yi','最后一次北伐的魏军对手','v035-b0017')]
    by_id['guanyu']['relations'].append(rel('luxun','其前线接替和谦逊书信降低戒备','v058-b0005','v058-b0007'))
    by_id['lumeng']['relations'].append(rel('luxun','推荐接替前线，随后同为荆州前部','v058-b0005','v058-b0007'))
    # Existing Lu Xun / Lu Su biographies already describe 219, 222 and the boundary talks.
    for person in people:
        person.setdefault('eventIds', [])
    return people
